INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(119650, 'ruRU', '', 'Как увлекательно. Этот Нат Пэгл похож на настоящего искателя приключений!', 24330),
(119651, 'ruRU', '', 'Ага! Успех!', 24330),
(119652, 'ruRU', '', 'Тебе б стоило поискать кого, кто знает об этой книге побольше. Думаю, тут намекают на что-то намного больше, чем просто денёк рыбалки!', 24330),
(119656, 'ruRU', '', 'Привет, милашка! Будь осторожен, если собираешься в Кратер Даларана — там довольно крутой обрыв.\n\nХотя у меня как раз случайно есть планеры на продажу, если понадобится.\n\n10 золота.\n\nВозврату не подлежит.', 24330),
(119661, 'ruRU', '', 'Хороший выбор! Обязательно используй его до того, как коснёшься земли. После этого от него толку мало.', 24330),
(119683, 'ruRU', '', 'Боюсь, я не знаю.\n\nЛишь крестоносцы, что убили его, знают правду, и никто из их рядов не выжил, чтобы раскрыть её.\n\nЯ бы поискал ответы в их бывших крепостях.', 24330),
(119710, 'ruRU', '', 'Все каналы активны. Можешь усилить питание?', 24330),
(119741, 'ruRU', '', 'Это риск, но Храм будет уязвим в любом случае. Нам следует держаться вместе.', 24330),
(119742, 'ruRU', '', 'Что, если незнакомец не прибудет, как обещал? Можем ли мы доверять его слову?', 24330),
(119746, 'ruRU', '', 'Храм Астрального Света в опасности. Вместе, рыцари Серебряной Руки, мы можем дать последний бой Балназару.', 24330),
(119748, 'ruRU', '', 'Я готов покинуть это место и никогда не оборачиваться.', 24330),
(119767, 'ruRU', '', 'Предатели!', 24330),
(119768, 'ruRU', '', 'Умрите, последователи лжекороля!', 24330),
(119769, 'ruRU', '', 'Твой лживый король-бог не может спасти тебя теперь!', 24330),
(119770, 'ruRU', '', 'За Королеву!', 24330),
(119771, 'ruRU', '', 'Сковальд падёт!', 24330),
(119772, 'ruRU', '', 'Глупый мальчишка. Думаешь, твои демонические фокусы спасут тебя от моего гнева?', 24330),
(119773, 'ruRU', '', 'Может, ты убил своего отца. Может, ты убил своих братьев. Но это НЕ даёт тебе права править нашим народом!', 24330),
(119775, 'ruRU', '', 'Ты... больше не... мой сын...', 24330),
(119777, 'ruRU', '', 'Выбирай, но выбирай с умом. Судьба Расколотых островов в твоих руках.', 24330),
(119779, 'ruRU', '', 'Это, вероятно, путь в один конец. Детерок наверняка ожидает нас. Дай знать, когда будешь готов.', 24330),
(119780, 'ruRU', '', 'Свет направляет мой меч!', 24330),
(119781, 'ruRU', '', 'Ищи глубоко свою внутреннюю силу.', 26972),
(119782, 'ruRU', '', 'Мы стоим вместе.', 26972),
(119783, 'ruRU', '', 'Я буду сражаться во имя Элуны!', 24330),
(119784, 'ruRU', '', 'Пусть Свет направляет меня.', 24330),
(119785, 'ruRU', '', 'Увидимся в ШР:7. Удачи, $n.', 24330),
(119806, 'ruRU', '', 'Паря в воздухе, ищи потоки тёплого воздуха, чтобы удерживаться в полёте. Эти чувства будут для тебя новыми, и ты привыкнешь к ним со временем.', 24330),
(119807, 'ruRU', '', 'Используй хвостовые перья, чтобы управлять полётом. Возможно, ты непривычен к использованию этой мышцы — обязательно потренируйся немного, прежде чем врезаться в дерево!', 24330),
(119808, 'ruRU', '', 'Другие птицы могут проявить интерес к твоей новой форме. Будь осторожен с... романтическим поведением.', 24330),
(119809, 'ruRU', '', 'Твой клюв нужен не только для болтовни — держи себя в порядке и чисти перья, иначе рискуешь заразиться жучками!', 24330),
(119810, 'ruRU', '', 'Будь предупреждён: ты почувствуешь СИЛЬНОЕ желание есть червей. Не могу это подчеркнуть достаточно — не ешь червей, ты об этом пожалеешь.', 24330),
(119811, 'ruRU', '', 'Когда расправляешь крылья, наклоняй их против встречных потоков ветра, чтобы подняться в воздух.', 24330),
(119812, 'ruRU', '', 'Может потребоваться момент, чтобы твоё зрение привыкло к новому положению глаз. Возможно, лучше иметь рядом насест.', 24330),
(119815, 'ruRU', '', 'Мы не позволим еретикам закончить то, что они начали.\n\nДух нашего лидера может быть потерян в Пустоте, но мы сохраним её тело в безопасности, пока его не удастся вернуть.', 24330),
(119816, 'ruRU', '', 'С возвращением нашего лидера к нам Забытые Тени могут восстать снова.', 24330),
(119818, 'ruRU', '', 'Азерот никогда прежде не сталкивался с полной силой Пылающего Легиона, но с отвагой и усердием Эбонический Клинок одержит победу.', 24330),
(119829, 'ruRU', '', 'Мы понесём эту тяжесть, Долинник. Прояви немного веры.', 24330),
(119832, 'ruRU', '', 'Подлые мистики Хауствальда продолжают развращать души наших павших воинов. Войди в это место, куда мои сёстры и я не смеем ступить, и уничтожь их развращающие тёмные руны.', 24330),
(119833, 'ruRU', '', 'Благодарю, защитник. Если бы мистиков оставили в покое, эти тёмные руны забрали бы бесчисленное множество других душ Валарьяров.', 24330);
